var wanted = new HashSet<string>{"Doors","Windows","Parking","Plumbing Fixtures","Specialty Equipment","Generic Models","Columns","Structural Columns","Casework","Furniture","Mechanical Equipment"};
var rows = new List<object>();
var counts = new Dictionary<string,int>();
foreach (FamilySymbol s in new FilteredElementCollector(doc).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>()) {
  if (s.Category == null || !wanted.Contains(s.Category.Name)) continue;
  string cat = s.Category.Name;
  if (!counts.ContainsKey(cat)) counts[cat] = 0;
  counts[cat]++;
  if (rows.Count >= 200) continue;
  string pt = "";
  try { pt = s.Family.FamilyPlacementType.ToString(); } catch {}
  var dims = new Dictionary<string,string>();
  foreach (string pn in new[]{"Width","Length","Depth","Height"}) {
    try { var p = s.LookupParameter(pn); if (p != null && p.StorageType == StorageType.Double) dims[pn] = Math.Round(p.AsDouble()*304.8).ToString(); } catch {}
  }
  rows.Add(new { id = s.Id.IntegerValue, cat = cat, family = s.FamilyName, type = s.Name, placement = pt, dimsMm = dims });
}
return new { categoryCounts = counts, shown = rows.Count, symbols = rows };
